changeSet.sql:
-- Create default headquarters address INSERT INTO address (id, tenant_id, street, house_number, postal_code, city, iso_country) SELECT gen_random_uuid(), tenant_id, 'Sous les chênes', '109A', '2944', 'Bonfol', 'CH' FROM salon WHERE NOT EXISTS ( SELECT 1 FROM address WHERE street = 'Sous les chênes' AND house_number = '109A' AND postal_code = '2944' ) GROUP BY tenant_id;
-- Create default bank account per tenant INSERT INTO bank_account (id, tenant_id, iban, account_holder) SELECT gen_random_uuid(), tenant_id, 'CH0780808002029014938', 'L''Ajoie de mieux vivre' FROM salon WHERE NOT EXISTS ( SELECT 1 FROM bank_account WHERE iban = 'CH0780808002029014938' ) GROUP BY tenant_id;
-- Update salon with default address and bank account UPDATE salon s SET headquarters_address_id = ( SELECT a.id FROM address a WHERE a.street = 'Sous les chênes' AND a.house_number = '109A' AND a.tenant_id = s.tenant_id LIMIT 1 ), event_address_id = ( SELECT a.id FROM address a WHERE a.street = 'Sous les chênes' AND a.house_number = '109A' AND a.tenant_id = s.tenant_id LIMIT 1 ), bank_account_id = ( SELECT ba.id FROM bank_account ba WHERE ba.iban = 'CH0780808002029014938' AND ba.tenant_id = s.tenant_id LIMIT 1 );

-- For H2, use RANDOM_UUID() instead -- Create default headquarters address INSERT INTO address (id, tenant_id, street, house_number, postal_code, city, iso_country) SELECT DISTINCT RANDOM_UUID(), tenant_id, 'Sous les chênes', '109A', '2944', 'Bonfol', 'CH' FROM salon WHERE NOT EXISTS ( SELECT 1 FROM address WHERE street = 'Sous les chênes' AND house_number = '109A' AND postal_code = '2944' );
-- Create default bank account per tenant INSERT INTO bank_account (id, tenant_id, iban, account_holder) SELECT DISTINCT RANDOM_UUID(), tenant_id, 'CH0780808002029014938', 'L''Ajoie de mieux vivre' FROM salon WHERE NOT EXISTS ( SELECT 1 FROM bank_account WHERE iban = 'CH0780808002029014938' );
-- Update salon with default address and bank account UPDATE salon s SET headquarters_address_id = ( SELECT a.id FROM address a WHERE a.street = 'Sous les chênes' AND a.house_number = '109A' AND a.tenant_id = s.tenant_id LIMIT 1 ), event_address_id = ( SELECT a.id FROM address a WHERE a.street = 'Sous les chênes' AND a.house_number = '109A' AND a.tenant_id = s.tenant_id LIMIT 1 ), bank_account_id = ( SELECT ba.id FROM bank_account ba WHERE ba.iban = 'CH0780808002029014938' AND ba.tenant_id = s.tenant_id LIMIT 1 );
